// Check Band + BXH: chỉ xác nhận khi có dữ liệu thực tế từ game.
let aioRankCache={name:'',rank:null,checked:0,pending:false},aioBanCache={name:'',banned:false,checked:0};
const aioNorm=v=>String(v||'').normalize('NFC').trim().toLocaleLowerCase('vi');
function aioCheckRank(name,rankText=""){
 const out=document.getElementById('aio-profile-check');if(!out)return;
 const normalized=aioNorm(name);
 if(!normalized||/chưa đọc|đang đọc/i.test(name)){out.textContent='⏳ Chưa xác minh Band / xếp hạng';return;}
 if(aioRankCache.name!==normalized){aioRankCache={name:normalized,rank:null,checked:0,pending:false};aioBanCache={name:normalized,banned:false,checked:0};}
 // Dò trực tiếp tên nhân vật + "hạng N" trong thông báo BXH, kể cả khi bảng không có class rank.
 const roots=[...document.querySelectorAll('[id*=rank i],[class*=rank i],[id*=leader i],[class*=leader i],table,[id*=board i],[class*=board i],[role=dialog],#modal')].filter(el=>el.offsetWidth||el.offsetHeight||el.getClientRects().length);
 let found=null;
 const escReg=s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
 const namePattern=escReg(String(name).trim()).replace(/\\ /g,'\\s+');
 const re=new RegExp(namePattern+'\\s*[:：]\\s*hạng\\s*(\\d{1,8})\\b','i');
 // Kiểm tra toàn bộ văn bản hiển thị: bảng xếp hạng có thể render bằng div không mang class cụ thể.
 const textSources=[rankText,...roots.map(el=>el.innerText||''),document.body?.innerText||''];
 for(const txt of textSources){
   const match=txt.match(re);
   if(match){found=Number(match[1]);break;}
 }
 // Dò các hàng trong bảng: thứ hạng có thể nằm ở cột đầu, không có chữ "Hạng".
 if(found===null)for(const root of roots){
   const rows=[...root.querySelectorAll('tr,li,[class*=row i]')];
   for(const row of rows.slice(0,2000)){
     const txt=(row.innerText||'').trim();if(!txt||txt.length>350)continue;
     const parts=txt.split(/\n|\t| {2,}/).map(x=>x.trim()).filter(Boolean);
     if(!parts.some(x=>aioNorm(x)===normalized))continue;
     const match=txt.match(/(?:hạng|rank|#)\s*[:#.]?\s*(\d{1,8})/i)||txt.match(/^\s*(\d{1,8})\s*[.\-)]?(?:\s|$)/);
     if(match){found=Number(match[1]);break;}
   }
   if(found!==null)break;
 }
 // Theo quy tắc BXH của máy chủ: chờ quản trị duyệt nghĩa là Band.
 const allText=rankText+'\n'+(document.body?.innerText||'');
 const lines=allText.split(/\n/).map(x=>x.trim()).filter(Boolean);
 const pendingRe=new RegExp(escReg(String(name).trim()).replace(/\\ /g,'\\s+')+'\\s*[:：]\\s*(?:đang\\s+)?chờ\\s+(?:quản\\s+trị\\s+)?duyệt','i');
 const pending=lines.some(line=>line.length<450&&pendingRe.test(line)) ||
   (allText.length<250000 && pendingRe.test(allText));
 if(found!==null&&found>0)aioRankCache={name:normalized,rank:found,checked:Date.now(),pending:false};
 else if(pending)aioRankCache={name:normalized,rank:null,checked:Date.now(),pending:true};
 // Chỉ đánh dấu Band khi có thông báo chờ duyệt hoặc thông báo khóa rõ ràng.
 const banFresh=aioBanCache.banned&&Date.now()-aioBanCache.checked<3600000;
 if(aioRankCache.pending){out.textContent='❌ ( Band )';out.style.color='#ff6666';}
 else if(aioRankCache.rank!==null){out.textContent='✅ Hạng '+aioRankCache.rank;out.style.color='#8ff0a0';}
 else if(banFresh){out.textContent='❌ ( Band )';out.style.color='#ff6666';}
 else{out.textContent='⏳ Chưa xác minh Band / xếp hạng';out.style.color='#a9bdca';}
}
// Chỉ ghi nhận thông báo khóa tài khoản nếu nêu rõ trạng thái khóa/Band.
const aioBanObserver=new MutationObserver(records=>{
 const name=document.getElementById('aio-profile-name')?.textContent?.trim();if(!name)return;
 for(const record of records)for(const node of record.addedNodes){
   const el=node.nodeType===1?node:node.parentElement;
   if(!el||!el.closest('#toast,#notifications,[role=alert],.toast,.notification'))continue;
   const msg=(node.textContent||'').slice(0,500);
   if(/(?:tài khoản|account|nhân vật).{0,50}(?:bị khóa|bị ban|banned)|(?:bị khóa|banned).{0,50}(?:tài khoản|account|nhân vật)/i.test(msg))aioBanCache={name:aioNorm(name),banned:true,checked:Date.now()};
 }
});
aioBanObserver.observe(document.documentElement,{subtree:true,childList:true});
setInterval(()=>{const n=document.getElementById('aio-profile-name')?.textContent?.trim();if(n)aioCheckRank(n)},5000);
let aioRankBusy=false,aioRankLast=0;
async function aioAutoRank(){
 if(aioRankBusy||Date.now()-aioRankLast<60000||document.hidden)return;
 const name=document.getElementById('aio-profile-name')?.textContent?.trim();
 const modal=document.querySelector('#modal');
 if(!name||!modal||!modal.classList.contains('hidden'))return;
 const direct=window.__VLTK_AIO_OPEN_RANK;
 const buttons=[...document.querySelectorAll('button,[role=button]')];
 const btn=buttons.find(b=>/xếp hạng/i.test(b.textContent||'')&&!b.closest('#vltk-only-reborn,#vltk-aio-profile')&&b.getClientRects().length);
 if(typeof direct!=='function'&&!btn)return;
 aioRankBusy=true;aioRankLast=Date.now();
 document.documentElement.classList.add('vltk-aio-rank-silent');
 let opened=false;
 try{
   if(typeof direct==='function')direct();else btn.click();
   opened=true;
   await new Promise(resolve=>setTimeout(resolve,2200));
   aioCheckRank(name,modal.innerText||modal.textContent||'');
 }catch(e){console.warn('[AIO auto rank]',e)}finally{
   if(opened&&!modal.classList.contains('hidden')){
     const close=document.querySelector('#mClose');
     if(close)close.click();
     // Không ép class hidden: để game tự dọn trạng thái modal.
   }
   document.documentElement.classList.remove('vltk-aio-rank-silent');aioRankBusy=false;
 }
}
setInterval(aioAutoRank,10000);setTimeout(aioAutoRank,8000);
let xpSamples=[],lastProfile=null;
const fmtXp=n=>Number.isFinite(n)?new Intl.NumberFormat('vi-VN',{maximumFractionDigits:0}).format(Math.max(0,n)):'--';
function profileTick(){
 const get=window.__VLTK_AIO_ACTIONS?.profile;
 const p=typeof get==='function'?get():null;
 if(!p||!p.level){
   // HUD fallback: bảng thông tin vẫn hiển thị cấp khi game không cung cấp đối tượng nội bộ.
   const lvText=document.querySelector('#lv')?.textContent||'';
   const level=Number((lvText.match(/\d+/)||[])[0])||0;
   const nameEl=document.querySelector('#playerName,#charName,#nameLbl,[data-player-name]');
   document.getElementById('aio-profile-name').textContent=nameEl?.textContent?.trim()||'Chưa đọc được tên nhân vật';
   aioCheckRank(document.getElementById('aio-profile-name').textContent);
   document.getElementById('aio-profile-level').textContent=level?String(level)+'/--':'--/--';
   document.getElementById('aio-profile-reborn').textContent='--';
   document.getElementById('aio-profile-target').textContent='Chưa lấy được dữ liệu chuyển sinh từ game';
   document.getElementById('aio-profile-eta').textContent='⏳ Chưa thể tính thời gian chuyển sinh';
   document.getElementById('aio-profile-rate').textContent='Đang chờ game cung cấp EXP và cấp chuyển sinh';
   return;
 }
 const now=Date.now();
 document.getElementById('aio-profile-name').textContent=p.name;
 aioCheckRank(p.name);
 document.getElementById('aio-profile-level').textContent=String(p.level)+'/'+String(p.need);
 document.getElementById('aio-profile-reborn').textContent=String(p.reborn)+' lần';
 document.getElementById('aio-profile-target').textContent='Mốc tiếp theo: cấp '+p.need+' · EXP còn '+fmtXp(p.remainingXp);
 const etaEl=document.getElementById('aio-profile-eta'),rateEl=document.getElementById('aio-profile-rate');
 if(p.level>=p.need){etaEl.textContent='♻️ Đã đủ cấp chuyển sinh';rateEl.textContent='Chờ Auto chuyển sinh';return;}
 if(lastProfile && (p.reborn!==lastProfile.reborn||p.level<lastProfile.level||p.need!==lastProfile.need))xpSamples=[];
 // Chỉ cộng EXP tăng thực tế, kể cả qua nhiều lần lên cấp; bỏ các lần reset do chuyển sinh.
 if(lastProfile && p.reborn===lastProfile.reborn && p.level>=lastProfile.level){
   let delta=0;
   if(p.level===lastProfile.level)delta=p.xp-lastProfile.xp;
   else if(p.level-lastProfile.level<30){
     delta=Math.max(0,lastProfile.expToNext-lastProfile.xp)+p.xp;
     // Cộng đủ EXP cho các cấp đã đi qua.
     const oldGet=lastProfile.level;
     for(let lv=oldGet+1;lv<p.level;lv++){
       // Khi nhảy nhiều cấp, không có bảng exp từng cấp từ HUD; tránh đoán tốc độ.
       delta=NaN;break;
     }
   }
   if(Number.isFinite(delta)&&delta>0)xpSamples.push({time:now,delta});
 }
 lastProfile=p;
 xpSamples=xpSamples.filter(x=>now-x.time<=180000);
 const sum=xpSamples.reduce((a,x)=>a+x.delta,0);
 const span=xpSamples.length?Math.max(15000,Math.min(180000,now-xpSamples[0].time+15000)):0;
 const rate=span>0?sum/span*1000:0;
 if(rate<=0){etaEl.textContent='⏳ Đang đo EXP để ước tính...';rateEl.textContent='Cần nhân vật nhận EXP thực tế';return;}
 const seconds=p.remainingXp/rate;
 if(!Number.isFinite(seconds)||seconds<0){etaEl.textContent='⏳ Chưa đủ dữ liệu';return;}
 const hours=Math.floor(seconds/3600),minutes=Math.ceil(seconds%3600/60);
 etaEl.textContent='⏳ Dự kiến CS sau: '+(hours?hours+' giờ ':'')+minutes+' phút';
 rateEl.textContent='Tốc độ gần đây: '+fmtXp(rate*60)+' EXP/phút · chỉ là ước tính';
}
