let lagBusy=false,horseBusy=false,lastHorseBuy=0;
function localDay(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function getHorseDaily(){let x;try{x=JSON.parse(localStorage.getItem(horseDailyKey)||'{}')}catch(_){x={}};if(x.day!==localDay())x={day:localDay(),count:0,show:0,sold:0,ky:0,toi:0};return x}
function saveHorseDaily(x){localStorage.setItem(horseDailyKey,JSON.stringify(x))}
function disableLagNoMoney(){lagUI.info.textContent=lagNoMoney}
function processHorseInventory(){
 try{const api=window.__VLTK_AIO_PURCHASE;return api?.processHorseInventory?.()}
 catch(err){console.warn('[VLTK Mở ngựa] Lỗi xử lý ngựa',err);return null}
}
function horseComplete(){horseMessage=horseMax();horseUI.info.textContent=horseMessage}
function disableHorseNoMoney(){horseMessage=horseNoMoney();horseUI.info.textContent=horseMessage}
function horseRecord(opened,daily){
 daily.count++;
 const item=opened?.it;
 if(item){const tier=opened.tier;
  if(tier==='ky')daily.ky=(daily.ky||0)+1;
  if(tier==='toi')daily.toi=(daily.toi||0)+1;
 }
 saveHorseDaily(daily);
}

lagUI.check.onchange=()=>{lagOn=lagUI.check.checked;localStorage.setItem(lagKey,lagOn?'1':'0');lagUI.info.textContent=lagDefault};
horseUI.check.onchange=()=>{horseOn=horseUI.check.checked;localStorage.setItem(horseKey,horseOn?'1':'0');horseMessage=horseDefault;horseUI.info.textContent=horseMessage};
async function lagTick(){
 if(!lagOn||lagBusy||window.__VLTK_AIO_GLOBAL_PAUSED)return;
 const api=window.__VLTK_AIO_PURCHASE;if(!api)return;
 const state=api.state();if(!state?.ready)return;
 lagBusy=true;
 try{
  for(const kind of ['xp','luck']){
   if(!lagOn)break;
   if((kind==='xp'?state.expRemaining:state.luckRemaining)>0)continue;
   const result=api.buyLag(kind);
   if(result?.noMoney){disableLagNoMoney();break}
   if(!result?.ok)break;
   lagUI.info.textContent=lagDefault;
  }
 }catch(err){console.warn('[VLTK Mua Lag]',err)}finally{lagBusy=false}
}
async function horseTick(){
 if(!horseOn||horseBusy||window.__VLTK_AIO_GLOBAL_PAUSED)return;
 const api=window.__VLTK_AIO_PURCHASE;if(!api)return;
 const state=api.state();if(!state?.ready||!state.server3)return;
 const daily=getHorseDaily();
 if(daily.count>=80){horseComplete();return}
 if(state.bagFree<=0)return; // Hành trang đầy: chờ, không mua.
 if(Date.now()-lastHorseBuy<7000)return;
 horseBusy=true;
 try{
  let opened;
  if(state.horseCount>0){opened=await api.openHorse()}
  else{
   if(state.gold<200000000){disableHorseNoMoney();return}
   lastHorseBuy=Date.now();
   const bought=await api.buyHorse();
   if(!bought?.ok){if(bought?.noMoney||/không đủ tiền|thiếu tiền/i.test(bought?.msg||''))disableHorseNoMoney();return}
   opened=await api.openHorse();
  }
  if(!opened?.ok)return;
  horseRecord(opened,daily);
  if(opened.it){const post=await api.finalizeHorse(opened.it);if(post?.shared){daily.show=(daily.show||0)+1;saveHorseDaily(daily)}if(!post?.ok)console.warn('[VLTK Mở ngựa]',post?.msg)}
  // Cất hai loại quý, mở khóa và bán những ngựa còn lại ngay sau khi mở.
  const processed=processHorseInventory();
  if(processed?.ok&&processed.sold>0){daily.sold=(daily.sold||0)+processed.sold;saveHorseDaily(daily)}
  if(processed?.blocked)console.warn('[VLTK Mở ngựa] Mã trường đầy, còn',processed.blocked,'ngựa quý trong túi');
  if(daily.count>=80)horseComplete();
  else {horseMessage=horseProgress();horseUI.info.textContent=horseMessage}
 }catch(err){console.warn('[VLTK Mở ngựa]',err)}finally{horseBusy=false}
}
setInterval(()=>{
 const daily=getHorseDaily();
 if(!horseOn){horseMessage=horseDefault;}
 else if(daily.count>=80){horseMessage=horseMax();}
 else if(horseMessage!==horseNoMoney()){horseMessage=horseProgress();}
 horseUI.info.textContent=horseMessage;
 lagTick();horseTick();
},1200);

 // Lưu theo phiên tab: giữ nguyên khi đổi map/F5, reset khi đóng tab hoặc sang ngày mới.
 // Bộ đếm lưu bền vững, chỉ xóa khi nhấn nút reset. Không reset do đổi map, F5, 00h.
 const chestSessionStats=new Map();
 const chestStatsPrefix='vltk_aio_chest_stats_manual_v437_';
 const chestStableKey='vltk_aio_chest_stats_daily_v444018_';
 const chestDate=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Ho_Chi_Minh',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
 const chestLegacyPrefix='vltk_aio_chest_stats_v435_';
 function chestCharacter(){return 'stable'}
 function chestStorageKey(character){return chestStableKey+chestDate()}
 function chestEntry(character){
   character='stable';
   if(chestSessionStats.has(character)){const current=chestSessionStats.get(character);if(current.day===chestDate())return current;chestSessionStats.delete(character)}
   let saved=null;
   try{saved=JSON.parse(localStorage.getItem(chestStorageKey(character))||'null')}catch(e){}
   if(false&&!saved){try{
     const candidates=[];
     for(let i=0;i<localStorage.length;i++){
       const key=localStorage.key(i);
       if(key&&key.startsWith(chestStatsPrefix)){
         try{const v=JSON.parse(localStorage.getItem(key)||'null');if(v)candidates.push(v)}catch(_){}
       }
     }
     if(candidates.length)saved=candidates.reduce((best,v)=>(Number(v.opened||0)+Number(v.exchange||0)+Number(v.tn||0))>(Number(best.opened||0)+Number(best.exchange||0)+Number(best.tn||0))?v:best);
   }catch(_){}}
   const entry=saved?{baseline:saved.baseline===null||!Number.isFinite(Number(saved.baseline))?null:Number(saved.baseline),opened:Math.max(0,Number(saved.opened)||0),tn:Math.max(0,Number(saved.tn)||0),exchange:Math.max(0,Number(saved.exchange)||0),lastTotal:Number.isFinite(Number(saved.lastTotal))?Number(saved.lastTotal):null}:{baseline:null,opened:0,tn:0,exchange:0,lastTotal:null};
   entry.day=chestDate();chestSessionStats.set(character,entry);return entry;
 }
 function saveChestEntry(character,entry){character='stable';try{localStorage.setItem(chestStorageKey(character),JSON.stringify(entry))}catch(e){}}
 function updateChestCount(){
   const character=chestCharacter(),entry=chestEntry(character);
   try{const stats=window.__VLTK_AIO_CHEST_STATS?.();if(stats&&Number.isFinite(Number(stats.chests))){
     const total=Number(stats.chests);
     if(entry.lastTotal===null){
       if(entry.baseline!==null&&total>=entry.baseline)entry.opened=Math.max(entry.opened,total-entry.baseline);
       entry.lastTotal=total;
     }else if(total>entry.lastTotal){entry.opened+=total-entry.lastTotal;entry.lastTotal=total}
     else if(total<entry.lastTotal){entry.lastTotal=total} // Chuyển map/đổi phiên thống kê: không trừ số đã đếm.
     if(entry.baseline===null)entry.baseline=total;
   }}catch(e){}
   saveChestEntry(character,entry);
   chestCount.textContent='Mở : '+entry.opened+' Tiềm năng : '+(entry.opened*5);
 }
 // Ghi nhận chính xác từng lần mở thành công, kể cả khi thống kê máy chủ không đổi ngay.
 window.addEventListener('vltk-aio-chest-open',e=>{
   const detail=e.detail||{},character=String(detail.character||chestCharacter());
   const entry=chestEntry(character),total=Number(detail.total);
   if(Number.isFinite(total)){
     if(entry.lastTotal===null){entry.opened+=1;entry.lastTotal=total}
     else if(total>entry.lastTotal){entry.opened+=total-entry.lastTotal;entry.lastTotal=total}
     else if(total===entry.lastTotal){/* sự kiện lặp: bỏ qua */}
     else {entry.opened+=1;entry.lastTotal=total}
   }else entry.opened+=1;
   entry.tn+=Math.max(0,Number(detail.tn)||0);
   saveChestEntry(character,entry);updateChestCount();
 });
 window.addEventListener('vltk-aio-chest-exchange',e=>{
   const character=String(e.detail?.character||chestCharacter());
   const amount=Math.max(0,Number(e.detail?.amount)||0);
   if(amount){const entry=chestEntry(character);entry.exchange+=1;saveChestEntry(character,entry)}
   updateChestCount();
 });
