const channelSelect=makeSelect(channelRow,'aio-channel',Array.from({length:10},(_,i)=>String(i+1)));
const CHANNEL_KEY='vltk_aio_selected_channel';channelSelect.value=localStorage.getItem(CHANNEL_KEY)||'1';
channelSelect.onchange=()=>{localStorage.setItem(CHANNEL_KEY,channelSelect.value);addon.train2Base=Number(channelSelect.value)||1;addon.train2Start=Date.now();twoCurrent=0;twoSince=0;twoPending=0;channelNextTry=0;channelPending=0;saveAddon()};
const PARTY_KEY='vltk_aio_reject_party',QUEST_KEY='vltk_aio_quest_xp',SELL_KEY='vltk_aio_sell_filter';
const partyRow=makeLine(),partyCheck=makeCheck(partyRow,'🚫 TC Tổ đội','aio-party');partyCheck.checked=localStorage.getItem(PARTY_KEY)==='1';window.__VLTK_AIO_REJECT_PARTY=partyCheck.checked;partyCheck.onchange=()=>{localStorage.setItem(PARTY_KEY,partyCheck.checked?'1':'0');window.__VLTK_AIO_REJECT_PARTY=partyCheck.checked;};
const questRow=makeLine(),questCheck=makeCheck(questRow,'📜 Dã tẩu','aio-quest');questRow.after(walletUI.wrap);

const WAR_DEFAULT='Tự vào chiến trường , chỉ vào 1 lần xong tắt , chủ yếu để làm nhiệm vụ dã tẩu';
const DUNGEON_DEFAULT='Tự vào phó bản , chỉ vào 1 lần xong tắt , chủ yếu để làm nhiệm vụ dã tẩu';
const warUI=makeAutoRow('⚔️ Chiến Trường','aio-auto-war',WAR_DEFAULT);
partyRow.after(warUI.wrap);
const dungeonUI=makeAutoRow('🏯 Phó Bản','aio-auto-dungeon',DUNGEON_DEFAULT);
walletUI.wrap.after(dungeonUI.wrap);
const instanceJobs=[{ui:warUI,kind:'war'},{ui:dungeonUI,kind:'dungeon'}];
for(const job of instanceJobs){
 job.state='idle';job.startedAt=0;job.character='';job.entered=false;
 job.ui.check.checked=false;
 job.ui.info.style.display='block';
}
function aioInstanceCounts(st,kind){
 if(kind==='war')return Math.max(0,Math.min(8,(Number(st.warTk)||0)+(Number(st.warSiege)||0)));
 return Math.max(0,Math.min(12,Number(st.dungeonUsed)||0));
}
function aioInstanceLimit(kind){return kind==='war'?8:12}
function aioInstanceLabel(job,st){
 const n=aioInstanceCounts(st,job.kind),limit=aioInstanceLimit(job.kind);
 if(n>=limit)return job.kind==='war'?`Đã vào ${n}/8 . Khoá tính năng , mở lại vào thứ 2`:`Đã vào ${n}/12 . Khoá tính năng , mở lại vào ngày mai`;
 if(n>0)return job.kind==='war'?`Đã ${n}/8 lần chiến trường`:`Đã ${n}/12 lần phó bản`;
 return job.kind==='war'?WAR_DEFAULT:DUNGEON_DEFAULT;
}
function aioInstanceRefresh(st){
 if(!st||!st.ready)return;
 for(const job of instanceJobs){
  const full=aioInstanceCounts(st,job.kind)>=aioInstanceLimit(job.kind);
  job.ui.check.disabled=full;
  job.ui.check.parentElement.style.opacity=full?'.55':'1';
  if(full&&job.state!=='running'){job.ui.check.checked=false;job.state='idle';}
  job.ui.info.textContent=aioInstanceLabel(job,st);
  job.ui.info.style.display='block';
 }
}
for(const job of instanceJobs){
 job.ui.check.onchange=()=>{
  const api=window.__VLTK_AIO_INSTANCES,st=api&&api.status();
  if(st&&st.ready&&aioInstanceCounts(st,job.kind)>=aioInstanceLimit(job.kind)){
   job.ui.check.checked=false;job.state='idle';aioInstanceRefresh(st);return;
  }
  job.state=job.ui.check.checked?'waiting':'idle';job.startedAt=0;job.entered=false;
  if(!job.ui.check.checked&&st&&st.ready)aioInstanceRefresh(st);
 };
}
let instanceTickBusy=false;
setInterval(()=>{
 if(instanceTickBusy)return;
 const api=window.__VLTK_AIO_INSTANCES;if(!api)return;
 instanceTickBusy=true;
 try{
  const st=api.status();if(!st.ready)return;
  aioInstanceRefresh(st);
  if(window.__VLTK_AIO_GLOBAL_PAUSED)return;
  for(const job of instanceJobs){
   if(!job.ui.check.checked)continue;
   if(job.state==='running'){
    if(st.active===job.kind||(job.kind==='war'&&['tk','siege'].includes(st.active)))continue;
    if(Date.now()-job.startedAt<2000)continue;
    job.ui.check.checked=false;job.state='idle';job.entered=true;
    aioInstanceRefresh(st);continue;
   }
   if(job.state!=='waiting')continue;
   if(st.active!=='none'||st.dead)continue;
   const result=job.kind==='war'?api.war():api.dungeon();
   if(result.ok){job.state='running';job.startedAt=Date.now();job.entered=true;}
   else if(['limit','limit-or-level','level'].includes(result.reason)){
    job.ui.check.checked=false;job.state='idle';
   }
   break;
  }
 }catch(e){console.warn('[VLTK Auto Chiến Trường/Phó Bản]',e)}finally{instanceTickBusy=false}
},2000);

// Dã Tẩu điều phối theo tiến độ nhiệm vụ, không tự tiêu lượt khi không cần.
let questOwnedTower=false,questTowerOldTarget=null,questTowerPreEnabled=false,questTaskKey='',questPending=null;
let questPickOwned=false,questPickTaskKey='';
function questReleasePickup(){
 if(!questPickOwned)return;
 // Chỉ phục hồi nếu Dã Tẩu đã bật; không tắt nếu người chơi đã bật từ trước.
 window.__VLTK_AIO_QUEST_PICK_ALL?.set(false);
 questPickOwned=false;questPickTaskKey='';
}
function questHandlePickup(q,key){
 const api=window.__VLTK_AIO_QUEST_PICK_ALL;if(!api)return;
 if(q.kind!=='picked'||q.have>=q.need){questReleasePickup();return;}
 if(questPickTaskKey!==key){questReleasePickup();questPickTaskKey=key;}
 const enabled=api.read();
 if(enabled===false&&api.set(true))questPickOwned=true;
}
let questTooltipText='Tự làm tống kim và phó bản , nếu hết lượt tự huỷ .';
let questDailyKey='',questDailyBaseline=null,questDailyLastStep=null,questDailyCompleted=0;
function questRefreshInfo(){
 const data=window.__VLTK_AIO_QUEST_DAILY?.();if(!data)return;
 const identity=data.character+':'+data.day;
 if(questDailyKey!==identity){
  questDailyKey=identity;questDailyCompleted=0;questDailyLastStep=data.step;
  try{const saved=JSON.parse(localStorage.getItem('vltk_aio_quest_daily_progress')||'null');if(saved?.key===identity){questDailyCompleted=Math.max(0,Number(saved.completed)||0);questDailyLastStep=Math.max(1,Number(saved.step)||data.step)}}catch(_){}
 }
 if(data.step>questDailyLastStep){questDailyCompleted+=data.step-questDailyLastStep;questDailyLastStep=data.step;}
 else if(data.step<questDailyLastStep)questDailyLastStep=data.step;
 try{localStorage.setItem('vltk_aio_quest_daily_progress',JSON.stringify({key:identity,step:questDailyLastStep,completed:questDailyCompleted}))}catch(_){}
 const n=questDailyCompleted,rerolls=Math.max(0,Number(data.rerolls)||0),max=Math.max(0,Number(data.rerollLimit)||50);
 // Chỉ cảnh báo khi thật sự hết lượt hủy VÀ nhiệm vụ hiện tại không thể thực hiện.
 // Không lấy riêng số lượt hủy để kết luận nhiệm vụ bị kẹt.
 const q=window.__VLTK_AIO_QUEST_STATUS?.();
 const unfinished=!!q&&q.need>0&&q.have<q.need;
 let cannotDo=false;
 if(unfinished&&['war','dungeon'].includes(q.kind)){
  const st=window.__VLTK_AIO_INSTANCES?.status?.();
  if(st?.ready){
   const used=aioInstanceCounts(st,q.kind),limit=aioInstanceLimit(q.kind);
   cannotDo=q.kind==='dungeon'
    ? !st.dungeons?.some(x=>x.remaining>0&&st.level>=x.level)
    : used>=limit||st.level<40;
  }
 }
 const blocked=max>0&&rerolls>=max&&unfinished&&cannotDo;
 questTooltipText=blocked?`Đã huỷ ${rerolls}/${max} trong ngày . Nhiệm vụ này hiện không làm được .`:`Tự làm tống kim và phó bản , nếu hết lượt tự huỷ .`;
}
setInterval(()=>{try{questRefreshInfo()}catch(e){console.warn('[AIO quest description]',e)}},2000);

function questStopOwnedTower(){
 if(questTowerOldTarget===null)return;
 // Chỉ tắt nếu Dã Tẩu là bên đã bật, giữ nguyên công tắc của người dùng.
 if(questOwnedTower&&towerCheck.checked){towerCheck.checked=false;towerCheck.dispatchEvent(new Event('change',{bubbles:true}));}
 if(questTowerOldTarget!==null){towerTarget.value=String(questTowerOldTarget);towerTarget.dispatchEvent(new Event('change',{bubbles:true}));}
 questOwnedTower=false;questTowerOldTarget=null;questTowerPreEnabled=false;
}
function questCoordinator(){
 if(!questCheck.checked||window.__VLTK_AIO_GLOBAL_PAUSED){if(!questCheck.checked){questStopOwnedTower();questReleasePickup();}return;}
 const q=window.__VLTK_AIO_QUEST_STATUS?.(),api=window.__VLTK_AIO_INSTANCES,st=api?.status?.();
 if(!q||!st?.ready)return;
 const key=q.kind+':'+q.taskId+':'+q.need;
 if(key!==questTaskKey){questTaskKey=key;questPending=null;questStopOwnedTower();questReleasePickup();}
 questHandlePickup(q,key);
 if(q.have>=q.need){questStopOwnedTower();return;}
 if(q.kind==='tower'){
  if(questTowerOldTarget===null){questTowerPreEnabled=towerCheck.checked;questOwnedTower=!towerCheck.checked;questTowerOldTarget=towerTarget.value;}
  if(towerTarget.value!=='1'){towerTarget.value='1';towerTarget.dispatchEvent(new Event('change',{bubbles:true}));}
  if(!towerCheck.checked){towerCheck.checked=true;towerCheck.dispatchEvent(new Event('change',{bubbles:true}));}
  // Sau nhiệm vụ, phục hồi chế độ cũ và giữ công tắc nếu trước đó đã bật.
  return;
 }
 questStopOwnedTower();
 if(!['dungeon','war'].includes(q.kind))return;
 const job=instanceJobs.find(x=>x.kind===q.kind);if(!job)return;
 const count=aioInstanceCounts(st,q.kind),limit=aioInstanceLimit(q.kind);
 const canEnter=q.kind==='dungeon'?st.dungeons?.some(x=>x.remaining>0&&st.level>=x.level):count<limit&&st.level>=40;
 if(!canEnter){
  if(q.canReroll&&!questPending){window.__VLTK_AIO_QUEST_REROLL_REQUEST=true;questPending='reroll';}
  return;
 }
 // Chờ hoàn tất lượt hiện tại; mỗi lần bật chỉ vào đúng một lượt.
 if(job.ui.check.checked||job.state==='running'||st.active!=='none'||st.dead)return;
 if(questPending&&questPending.kind===q.kind){
  if(count<=questPending.count)return; // chưa xác nhận đã tiêu lượt
  questPending=null;
 }
 job.ui.check.checked=true;
 job.ui.check.dispatchEvent(new Event('change',{bubbles:true}));
 questPending={kind:q.kind,count};
}
setInterval(()=>{try{questCoordinator()}catch(e){console.warn('[AIO Dã Tẩu coordinator]',e)}},2800);

questCheck.checked=localStorage.getItem(QUEST_KEY)==='1';questCheck.onchange=()=>localStorage.setItem(QUEST_KEY,questCheck.checked?'1':'0');
const sellRow=makeLine(),sellCheck=makeCheck(sellRow,'🧺 Bán đồ lọc','aio-sell');sellCheck.checked=localStorage.getItem(SELL_KEY)==='1';sellCheck.onchange=()=>localStorage.setItem(SELL_KEY,sellCheck.checked?'1':'0');
let lastSell=0,lastParty=0,lastQuest=0;
setInterval(()=>{
 if(window.__VLTK_AIO_GLOBAL_PAUSED)return;
 const actions=window.__VLTK_AIO_ACTIONS;if(!actions)return;
 const now=Date.now();
 if(partyCheck.checked&&now-lastParty>4500){lastParty=now;actions.rejectParty()}
 if(questCheck.checked&&now-lastQuest>2500){lastQuest=now;actions.quest()}
 if(sellCheck.checked&&now-lastSell>20000){lastSell=now;actions.sell()}
},1000);

// Bo sung Joystick, Train max, Train 2 map - chung menu, khong mo them panel.
const ADDON_KEY='vltk_aio_train_options_v23';
let addon={};try{addon=JSON.parse(localStorage.getItem(ADDON_KEY)||'{}')}catch(_){}
const saveAddon=()=>localStorage.setItem(ADDON_KEY,JSON.stringify(addon));
const joyRow=makeLine(),joyCheck=makeCheck(joyRow,'🕹 Joystick','aio-joystick');
const joyMode=makeSelect(joyRow,'aio-joystick-mode',['Sát thương','Kinh nghiệm']);
joyCheck.checked=!!addon.joystick;joyMode.value=addon.joyMode==='Kinh nghiệm'?'Kinh nghiệm':'Sát thương';
joyCheck.onchange=()=>{addon.joystick=joyCheck.checked;saveAddon()};
joyMode.onchange=()=>{addon.joyMode=joyMode.value;saveAddon()};
const maxRow=makeLine(),maxCheck=makeCheck(maxRow,'⚔️ Train max','aio-train-max');maxRow.after(horseUI.wrap);horseUI.wrap.after(lagUI.wrap);
const bossRow=makeLine(),bossCheck=makeCheck(bossRow,'🐉 Boss TG','aio-boss-tg');
const BOSS_TG_KEY='vltk_aio_boss_tg_v4410';bossCheck.checked=localStorage.getItem(BOSS_TG_KEY)==='1';bossCheck.onchange=()=>{localStorage.setItem(BOSS_TG_KEY,bossCheck.checked?'1':'0');if(!bossCheck.checked)bossTgRestore()};
maxCheck.checked=!!addon.trainMax;maxCheck.onchange=()=>{addon.trainMax=maxCheck.checked;saveAddon()};
const twoRow=makeLine(),twoCheck=makeCheck(twoRow,'🔄 Train 2','aio-train-two');
const twoMode=makeSelect(twoRow,'aio-train-two-mode',['6s','16s','25s']);
twoCheck.checked=!!addon.train2;twoMode.value=['6s','16s','25s'].includes(addon.train2Mode)?addon.train2Mode:'16s';
// Spam Thap 1 duoc uu tien; khong cho Train 2 map chay dong thoi.
const TOWER_PRIORITY_KEY='vltk_only_reborn_tower_enabled';
function disableTrain2ForTower(){
  if(!addon.train2&&!twoCheck.checked)return;
  addon.train2=false;twoCheck.checked=false;twoCurrent=0;twoSince=0;twoPending=0;
  channelNextTry=0;channelPending=0;saveAddon();
}
if(localStorage.getItem(TOWER_PRIORITY_KEY)==='1')disableTrain2ForTower();
twoCheck.onchange=()=>{
  if(twoCheck.checked&&localStorage.getItem(TOWER_PRIORITY_KEY)==='1'){
    twoCheck.checked=false;addon.train2=false;saveAddon();return;
  }
  addon.train2=twoCheck.checked;addon.train2Base=Number(channelSelect.value)||1;
  addon.train2Start=Date.now();saveAddon();
};
twoMode.onchange=()=>{addon.train2Mode=twoMode.value;addon.train2Start=Date.now();saveAddon()};
const addonStatus=document.createElement('div');addonStatus.style.cssText='font-size:11px;color:#9ad9ff;margin-top:3px';content.append(addonStatus);
// Train Max: goi truc tiep ham chuyen map cua game, khong phu thuoc tab log mo hay thu gon.
let maxNext=0;
function maxTick(){
 // Đồng bộ trực tiếp công tắc Train Max với tính năng đổi bãi theo cấp của game.
 // Vòng xử lý gốc chạy mỗi 2 giây và không cần giao diện Treo Game mở.
 const enabled=!!maxCheck.checked;
 if(window.__VLTK_AIO_TRAIN_MAX_NATIVE){
   const ok=window.__VLTK_AIO_TRAIN_MAX_NATIVE(enabled);
   if(enabled && !ok && Date.now()>maxNext){
     maxNext=Date.now()+9000;
     addonStatus.textContent='⚔️ Train Max: đang chờ nhân vật vào game';
   }
 }
}
// Đồng bộ kênh bằng trạng thái game Nw.ch, không dựa vào nhãn #stageLbl.
// Khi Train 2 map bật, kênh chọn là kênh gốc; chỉ đổi luân phiên trong cặp kênh.
let twoCurrent=0,twoSince=0,twoPending=0,twoPendingAt=0;
let channelNextTry=0,channelPending=0,channelPendingAt=0;
function hudChannel(){
 const fromGame=Number(window.__VLTK_AIO_ACTIONS?.currentChannel?.())||0;
 if(fromGame>=1&&fromGame<=10)return fromGame;
 const els=document.querySelectorAll('#channelLbl,#channelLabel,#svChannel,#serverChannel,[data-current-channel],#stageLbl');
 for(const el of els){const attr=el.getAttribute('data-current-channel');if(/^(10|[1-9])$/.test(attr||''))return +attr;
 const m=(el.textContent||'').match(/kênh\s*[:#-]?\s*(10|[1-9])(?:\D|$)/i);if(m)return +m[1];}
 return 0;
}
function channelTick(){if(window.__VLTK_AIO_GLOBAL_PAUSED)return;
 const now=Date.now(),actual=hudChannel(),base=Number(channelSelect.value)||1;
 if(!actual){addonStatus.textContent='🌐 Chưa đọc được kênh hiện tại';return;}
 if(channelPending){
  if(actual===channelPending){channelPending=0;channelPendingAt=0;channelNextTry=now+1200;}
  else if(now-channelPendingAt<6500)return;
  else {channelPending=0;channelNextTry=now+3000;}
 }
 if(now<channelNextTry)return;
 if(document.querySelector('#modal:not(.hidden)'))return;
 let desired=base;
 if(twoCheck.checked){
  const other=base===10?1:base+1;
  if(actual!==base&&actual!==other){desired=base;twoCurrent=0;twoSince=0;}
  else {
   if(actual!==twoCurrent){twoCurrent=actual;twoSince=now;twoPending=0;}
   if(!twoSince)twoSince=now;
   const period=(parseInt(twoMode.value,10)||16)*1000;
   const remain=period-(now-twoSince);
   if(remain>0){addonStatus.textContent=`🔄 Train 2 map: kênh ${actual} · còn ${Math.ceil(remain/1000)}s`;return;}
   desired=actual===base?other:base;
  }
 }else{twoCurrent=0;twoSince=0;twoPending=0;}
 if(actual===desired){channelNextTry=now+2000;return;}
 const ok=window.__VLTK_AIO_ACTIONS?.channel?.(desired);
 channelNextTry=now+(ok?1800:4000);
 if(ok){channelPending=desired;channelPendingAt=now;addonStatus.textContent=`🌐 Đang chuyển kênh ${actual} → ${desired}`;}
 else addonStatus.textContent=`🌐 Kênh ${actual} → ${desired}: đang chờ hệ thống cho đổi`;
}
function twoTick(){if(window.__VLTK_AIO_GLOBAL_PAUSED)return;channelTick()}
// Joystick gamepad ao: khi 6 giay khong thay EXP/sat thuong moi, di chuyen 1 giay.
const realGetGamepads=typeof navigator.getGamepads==='function'?navigator.getGamepads.bind(navigator):null;
const pad={id:'VLTK AIO recovery',index:0,connected:true,mapping:'standard',timestamp:0,axes:[0,0,0,0],buttons:Array.from({length:17},()=>({pressed:false,touched:false,value:0}))};
let joyUntil=0,joyLast=Date.now(),joyCooldown=0,joySample='',joyStep=0,joyPaused=false;
try{navigator.getGamepads=()=>joyUntil>Date.now()?[pad,...(realGetGamepads?Array.from(realGetGamepads()||[]).filter(Boolean):[])]:realGetGamepads?realGetGamepads():[]}catch(e){console.warn('[VLTK AIO] gamepad ao khong ho tro',e)}
function joyStop(){joyUntil=0;pad.axes[0]=pad.axes[1]=0;if(joyPaused){const ctrl=document.querySelector('#ctrlBtn');if(ctrl&&!ctrl.classList.contains('on'))ctrl.click();}joyPaused=false;joyCooldown=Date.now()+12000;joyLast=Date.now()}
function joyTick(){if(window.__VLTK_AIO_GLOBAL_PAUSED)return;
 if(window.__VLTK_AIO_GLOBAL_PAUSED){joyStop();return;}
 const now=Date.now();if(!joyCheck.checked){if(joyUntil||joyPaused)joyStop();joySample='';return}
 if(joyUntil){if(now>=joyUntil)joyStop();return}
 const ctrl=document.querySelector('#ctrlBtn');if(!ctrl?.classList.contains('on')){joyLast=now;return}
 const sample=joyMode.value==='Kinh nghiệm'?(document.querySelector('#lv')?.textContent||'')+'|'+(document.querySelector('#xpTxt')?.textContent||'')+'|'+(document.querySelector('#xpBar')?.style.width||''):(document.querySelector('#combatLog,#dmgLog,#battleLog')?.textContent||'').slice(-160);
 if(!sample){joyLast=now;return}
 if(sample!==joySample){joySample=sample;joyLast=now;return}
 if(now-joyLast<6000||now<joyCooldown||document.querySelector('#modal:not(.hidden)'))return;
 ctrl.click();joyPaused=true;const axes=[[1,0],[0,1],[-1,0],[0,-1]][joyStep++%4];pad.axes[0]=axes[0];pad.axes[1]=axes[1];joyUntil=now+1100;addonStatus.textContent='🕹 Joystick: thử di chuyển chống kẹt';
}
setInterval(()=>{try{maxTick();twoTick();joyTick()}catch(e){console.warn('[VLTK AIO add-ons]',e)}},500);

