for(const item of mainMenuOrder)if(item instanceof Node)content.appendChild(item);
// Thu gọn toàn bộ phần điều khiển: luôn giữ khung thông tin nhân vật hiển thị.
// Không thay đổi trạng thái bật/tắt của bất kỳ tính năng nào.
const compactKey='vltk_aio_controls_compact_v438';
const controlsWrap=document.createElement('div');controlsWrap.id='vltk-aio-controls-wrap';
