// Boss TG: use native boss battle entry and Vietnam time, no modal navigation.
let bossTgRunning=false,bossTgSession='',bossTgSaved=null,bossTgLastTry=0,bossTgLastRefresh=0,bossTgBusy=false,bossTgSeenOpen=false,bossTgFinishedSession='',bossTgFailures=0;
const BOSS_SNAPSHOT='vltk_aio_boss_restore_v4440';
const bossTgClock=()=>{const x=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Ho_Chi_Minh',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date());const v=Object.fromEntries(x.map(y=>[y.type,y.value]));return {day:v.year+'-'+v.month+'-'+v.day,h:+v.hour,m:+v.minute}};
function bossTgPause(){
 if(bossTgRunning)return;
 bossTgRunning=true;
 const ids=[];
 for(const check of content.querySelectorAll('input[type="checkbox"]')){
  if(check===bossCheck||check===speedCheck||!check.checked)continue;
  if(!check.id)continue;
  ids.push(check.id);check.checked=false;check.dispatchEvent(new Event('change',{bubbles:true}));
 }
 bossTgSaved={ids};
 try{localStorage.setItem(BOSS_SNAPSHOT,JSON.stringify({ids,at:Date.now()}))}catch(_){}
 window.__VLTK_AIO_GLOBAL_PAUSED=true;
}
function bossTgRestore(){
 bossTgRunning=false;
 // Không hủy STOP do người dùng đặt; khôi phục đúng cờ thủ công.
 window.__VLTK_AIO_GLOBAL_PAUSED=paused;
 let saved=bossTgSaved;
 if(!saved){try{saved=JSON.parse(localStorage.getItem(BOSS_SNAPSHOT)||'null')}catch(_){}}
 if(saved&&Array.isArray(saved.ids))for(const id of saved.ids){const check=document.getElementById(id);if(check&&!check.checked){check.checked=true;check.dispatchEvent(new Event('change',{bubbles:true}))}}
 bossTgSaved=null;localStorage.removeItem(BOSS_SNAPSHOT);
}
// Boss TG: prepare Tâm pháp ahead of both 12:00 and 21:00 sessions.
const BOSS_TP_KEY='vltk_aio_boss_tp_progress_v1';
let bossTpBusy=false,bossTpNext=0,bossTpSession='',bossTpPhase='';
function bossTpSchedule(t){const mins=t.h*60+t.m;const slots=[720,1260];const upcoming=mins<720?720:mins<1200?720:1260;const start=upcoming;return {start,session:t.day+'-'+Math.floor(start/60),minute:mins};}
function bossTpStep(){
 if(bossTpBusy||paused||!bossCheck.checked)return;
 const api=window.__VLTK_AIO_BOSS_TP,st=api?.status?.(),t=bossTgClock(),slot=bossTpSchedule(t);
 if(!st?.ready||!slot)return;
 const bossState=window.__VLTK_AIO_BOSS?.state?.();
 const inFight=slot.minute>=slot.start&&slot.minute<slot.start+15;
 const secondsNeeded=st.total*5+40;
 const leadMinutes=Math.max(2,Math.ceil(secondsNeeded/60));
 const preparing=slot.minute>=slot.start-leadMinutes&&slot.minute<slot.start;
 const finished=slot.minute>=slot.start+15||(bossTgFinishedSession===slot.session)||(bossTgSeenOpen&&!bossState?.open&&slot.minute>=slot.start);
 let phase=preparing?'tru':finished?'bao':null;
 if(!phase)return;
 const identity=slot.session+':'+phase;
 if(bossTpSession!==identity){bossTpSession=identity;bossTpPhase=phase;bossTpNext=0;}
 if(Date.now()<bossTpNext)return;
 const assigned=phase==='tru'?st.tru:st.bao;
 if(assigned===st.total&&st.available===0)return;
 bossTpBusy=true;
 try{
  if(st.assigned>0&&(st.assigned!==assigned)){
   if(!api.reset()){bossTpNext=Date.now()+15000;return;}
   bossTpNext=Date.now()+3500;return;
  }
  if(st.available>0){if(!api.add(phase)){bossTpNext=Date.now()+10000;return;}bossTpNext=Date.now()+3000+Math.random()*2000;}
 }finally{bossTpBusy=false}
}
setInterval(bossTpStep,1000);
async function bossTgTick(){
 if(bossTgBusy)return;
 try{const t=bossTgClock();if((t.h===12||t.h===21)&&t.m>=15)window.__VLTK_AIO_BOSS_TP?.closeReward?.()}catch(_){}
 // STOP thủ công luôn có ưu tiên cao hơn Boss TG.
 if(paused)return;
 const t=bossTgClock(),inWindow=(t.h===12||t.h===21)&&t.m<15,session=t.day+'-'+t.h;
 if(!bossCheck.checked||!inWindow||bossTgFinishedSession===session){if(bossTgRunning||localStorage.getItem(BOSS_SNAPSHOT))bossTgRestore();return}
 const api=window.__VLTK_AIO_BOSS;if(!api||!api.state().ready)return;
 if(Date.now()-bossTgLastRefresh>12000&&!api.state().busy){
  bossTgLastRefresh=Date.now();bossTgBusy=true;
  try{await api.refresh()}catch(e){console.warn('[Boss TG refresh]',e)}finally{bossTgBusy=false}
 }
 const st=api.state();
 if(st.open)bossTgSeenOpen=true;
 if(bossTgSeenOpen&&!st.open){bossTgFinishedSession=session;bossTgRestore();return}
 if(!st.open)return; // never pause normal auto just because the clock matches
 if(!bossTgRunning){bossTgSession=session;bossTgPause()}
 if(st.active||st.dead||st.busy||st.blocked)return;
 const wait=Math.min(60000,7000*Math.pow(1.6,Math.min(bossTgFailures,5)));
 if(Date.now()-bossTgLastTry<wait)return;
 bossTgLastTry=Date.now();bossTgBusy=true;
 try{const result=await api.enter();bossTgFailures=result?0:bossTgFailures+1}catch(e){bossTgFailures++;console.warn('[Boss TG enter]',e)}finally{bossTgBusy=false}
}
setInterval(bossTgTick,1500);

// v4.4.40 Guild automation: read state before a 500M contribution, persist uncertain attempt.
let guildBusy=false,guildNext=0;
const guildDay=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Ho_Chi_Minh',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
async function guildTick(){
 if(!guildToggle.checked||guildBusy||Date.now()<guildNext||window.__VLTK_AIO_GLOBAL_PAUSED)return;
 const api=window.__VLTK_AIO_GUILD;if(!api?.state?.().ready)return;
 guildBusy=true;guildNext=Date.now()+60000;
 try{
  const st=await api.inspect();if(!st?.member)return;
  if(st.role>=1){for(const name of st.requests.slice(0,8)){if(!guildToggle.checked)break;await api.accept(name)}return}
  const identity=api.state().character;if(!identity)return;
  const key='vltk_guild_500m_'+identity+'_'+guildDay();
  if(localStorage.getItem(key))return;
  if(st.dayGold>=500){localStorage.setItem(key,'already');return}
  if(st.dayLimit<500||st.dayGold!==0||api.state().gold<500000000)return;
  // Record attempt BEFORE network request; if response is lost, never blindly spend again.
  localStorage.setItem(key,'pending');
  const ok=await api.donate500();
  if(ok)localStorage.setItem(key,'done');
  else {const fresh=await api.inspect();if(fresh?.dayGold>=500)localStorage.setItem(key,'done');else localStorage.setItem(key,'uncertain')}
 }catch(e){console.warn('[VLTK Guild Auto]',e)}finally{guildBusy=false}
}
setInterval(()=>{void guildTick()},15000);

setTimeout(()=>{const t=bossTgClock();if(localStorage.getItem(BOSS_SNAPSHOT)&&!((t.h===12||t.h===21)&&t.m<15))bossTgRestore()},4500);


