    if(speedMode!=='Auto')return Number(localStorage.getItem('vltk_kemmy_speed_'+speedMode)||speedMode.slice(1))||1;
    return window.__VLTK_AIO_BOSS?.state?.().active?Math.max(1,Math.min(100,Number(localStorage.getItem('vltk_kemmy_speed_boss_world')||5))):speedInTower()?Number(localStorage.getItem('vltk_kemmy_speed_tower')||5):(speedLevel()!==null&&speedLevel()<Math.max(1,Number(localStorage.getItem('vltk_kemmy_speed_level_boundary')||40))?Number(localStorage.getItem('vltk_kemmy_speed_low')||5):Number(localStorage.getItem('vltk_kemmy_speed_high')||10));
